    var immex=api.MapGroup("/immex");
    immex.MapGet("/coverage",async(SaceDbContext db,CancellationToken ct)=>Results.Ok(await db.Annex24CoverageItems.AsNoTracking().Include(x=>x.OfficialSourceCitation).OrderBy(x=>x.Code).ToListAsync(ct)));
