    immex.MapPost("/programs",async(ImmexProgramRequest request,HttpContext ctx,SaceDbContext db,CancellationToken ct)=>{ValidateProgram(request);var number=request.ProgramNumber.Trim().ToUpperInvariant();if(await db.ImmexPrograms.AnyAsync(x=>x.ProgramNumber==number,ct))return Results.Conflict(Error("IMMEX_PROGRAM_DUPLICATE","El número de programa ya existe."));var item=new ImmexProgram{ProgramNumber=number,CompanyName=request.CompanyName.Trim(),Rfc=request.Rfc.Trim().ToUpperInvariant(),Status=request.Status,ValidFrom=request.ValidFrom,ValidTo=request.ValidTo,ProgramModality=Clean(request.ProgramModality),CertifiedCompanyStatus=Clean(request.CertifiedCompanyStatus),FiscalAddress=Clean(request.FiscalAddress),IndustrialPlantAddressesJson=Clean(request.IndustrialPlantAddressesJson),WarehouseAddressesJson=Clean(request.WarehouseAddressesJson),SourceType=request.SourceType};db.ImmexPrograms.Add(item);Audit(db,ctx,"IMMEX_PROGRAM_CREATED",item,$"Programa {item.ProgramNumber}; estado declarado {item.Status}.");await db.SaveChangesAsync(ct);return Results.Created($"/api/immex/programs/{item.Id}",item);});
    immex.MapPut("/programs/{id:guid}",async(Guid id,ImmexProgramRequest request,HttpContext ctx,SaceDbContext db,CancellationToken ct)=>{ValidateProgram(request);var item=await db.ImmexPrograms.FindAsync([id],ct);if(item is null)return Results.NotFound(Error("IMMEX_PROGRAM_NOT_FOUND","Programa IMMEX no localizado."));var number=request.ProgramNumber.Trim().ToUpperInvariant();if(await db.ImmexPrograms.AnyAsync(x=>x.Id!=id&&x.ProgramNumber==number,ct))return Results.Conflict(Error("IMMEX_PROGRAM_DUPLICATE","El número de programa ya existe."));item.ProgramNumber=number;item.CompanyName=request.CompanyName.Trim();item.Rfc=request.Rfc.Trim().ToUpperInvariant();item.Status=request.Status;item.ValidFrom=request.ValidFrom;item.ValidTo=request.ValidTo;item.ProgramModality=Clean(request.ProgramModality);item.CertifiedCompanyStatus=Clean(request.CertifiedCompanyStatus);item.FiscalAddress=Clean(request.FiscalAddress);item.IndustrialPlantAddressesJson=Clean(request.IndustrialPlantAddressesJson);item.WarehouseAddressesJson=Clean(request.WarehouseAddressesJson);item.SourceType=request.SourceType;item.UpdatedAt=DateTime.UtcNow;Audit(db,ctx,"IMMEX_PROGRAM_UPDATED",item,$"Programa {item.ProgramNumber} actualizado.");await db.SaveChangesAsync(ct);return Results.Ok(item);});

    immex.MapGet("/materials",async(Guid? programId,string? search,int page,int pageSize,SaceDbContext db,IConfiguration cfg,CancellationToken ct)=>{var q=db.ImmexMaterials.AsNoTracking().AsQueryable();if(programId.HasValue)q=q.Where(x=>x.ImmexProgramId==programId);if(!string.IsNullOrWhiteSpace(search))q=q.Where(x=>x.MaterialCode.Contains(search)||x.Description.Contains(search));return Results.Ok(await Page(q.OrderBy(x=>x.MaterialCode),page,pageSize,cfg,ct));});
    immex.MapPost("/materials",async(ImmexMaterialRequest request,HttpContext ctx,SaceDbContext db,CancellationToken ct)=>{await ValidateProgramExists(request.ImmexProgramId,db,ct);var code=Required(request.MaterialCode,"MaterialCode").ToUpperInvariant();if(await db.ImmexMaterials.AnyAsync(x=>x.ImmexProgramId==request.ImmexProgramId&&x.MaterialCode==code,ct))return Results.Conflict(Error("IMMEX_MATERIAL_DUPLICATE","El código de material ya existe en el programa."));var item=Material(request,code);db.ImmexMaterials.Add(item);Audit(db,ctx,"IMMEX_MATERIAL_CREATED",item,$"Material {code}.");await db.SaveChangesAsync(ct);return Results.Created($"/api/immex/materials/{item.Id}",item);});
    immex.MapPut("/materials/{id:guid}",async(Guid id,ImmexMaterialRequest request,HttpContext ctx,SaceDbContext db,CancellationToken ct)=>{var item=await db.ImmexMaterials.FindAsync([id],ct);if(item is null)return Results.NotFound(Error("IMMEX_MATERIAL_NOT_FOUND","Material no localizado."));var code=Required(request.MaterialCode,"MaterialCode").ToUpperInvariant();if(await db.ImmexMaterials.AnyAsync(x=>x.Id!=id&&x.ImmexProgramId==request.ImmexProgramId&&x.MaterialCode==code,ct))return Results.Conflict(Error("IMMEX_MATERIAL_DUPLICATE","El código de material ya existe en el programa."));item.ImmexProgramId=request.ImmexProgramId;item.MaterialCode=code;item.Description=Required(request.Description,"Description");item.TariffFraction=Tariff(request.TariffFraction);item.Nico=Clean(request.Nico);item.TigieUnit=Unit(request.TigieUnit);item.CommercialUnit=Clean(request.CommercialUnit);item.IsActive=request.IsActive;item.UpdatedAt=DateTime.UtcNow;Audit(db,ctx,"IMMEX_MATERIAL_UPDATED",item,$"Material {code} actualizado.");await db.SaveChangesAsync(ct);return Results.Ok(item);});
    immex.MapGet("/products",async(Guid? programId,string? search,int page,int pageSize,SaceDbContext db,IConfiguration cfg,CancellationToken ct)=>{var q=db.ImmexProducts.AsNoTracking().AsQueryable();if(programId.HasValue)q=q.Where(x=>x.ImmexProgramId==programId);if(!string.IsNullOrWhiteSpace(search))q=q.Where(x=>x.ProductCode.Contains(search)||x.Description.Contains(search));return Results.Ok(await Page(q.OrderBy(x=>x.ProductCode),page,pageSize,cfg,ct));});
    immex.MapPost("/products",async(ImmexProductRequest request,HttpContext ctx,SaceDbContext db,CancellationToken ct)=>{await ValidateProgramExists(request.ImmexProgramId,db,ct);var code=Required(request.ProductCode,"ProductCode").ToUpperInvariant();if(await db.ImmexProducts.AnyAsync(x=>x.ImmexProgramId==request.ImmexProgramId&&x.ProductCode==code,ct))return Results.Conflict(Error("IMMEX_PRODUCT_DUPLICATE","El código de producto ya existe en el programa."));var item=Product(request,code);db.ImmexProducts.Add(item);Audit(db,ctx,"IMMEX_PRODUCT_CREATED",item,$"Producto {code}.");await db.SaveChangesAsync(ct);return Results.Created($"/api/immex/products/{item.Id}",item);});
