    immex.MapGet("/inventory",async(Guid? programId,Guid? materialId,string? tariffFraction,string? nico,string? pedimento,string? status,string? dueStatus,DateTime? from,DateTime? to,string? sort,string? direction,int page,int pageSize,SaceDbContext db,IConfiguration cfg,CancellationToken ct)=>{var q=db.ImmexInventoryEntries.AsNoTracking().Include(x=>x.Material).AsQueryable();if(programId.HasValue)q=q.Where(x=>x.ImmexProgramId==programId);if(materialId.HasValue)q=q.Where(x=>x.MaterialId==materialId);if(!string.IsNullOrWhiteSpace(tariffFraction))q=q.Where(x=>x.TariffFraction==Tariff(tariffFraction));if(!string.IsNullOrWhiteSpace(nico))q=q.Where(x=>x.Nico==nico);if(!string.IsNullOrWhiteSpace(pedimento))q=q.Where(x=>x.PedimentoNumber.Contains(pedimento));if(Enum.TryParse<ImmexInventoryEntryStatus>(status,true,out var s))q=q.Where(x=>x.Status==s);if(Enum.TryParse<ImmexTemporalityOutcome>(dueStatus,true,out var d))q=q.Where(x=>x.TemporalityOutcome==d);if(from.HasValue)q=q.Where(x=>x.EntryDate>=from);if(to.HasValue)q=q.Where(x=>x.EntryDate<to.Value.Date.AddDays(1));q=(sort?.ToLowerInvariant(),direction?.ToLowerInvariant()) switch{("entrydate","asc")=>q.OrderBy(x=>x.EntryDate).ThenBy(x=>x.Id),("duedate","asc")=>q.OrderBy(x=>x.DueDate).ThenBy(x=>x.Id),("duedate",_)=>q.OrderByDescending(x=>x.DueDate).ThenBy(x=>x.Id),("availablequantity","asc")=>q.OrderBy(x=>x.AvailableQuantity).ThenBy(x=>x.Id),("availablequantity",_)=>q.OrderByDescending(x=>x.AvailableQuantity).ThenBy(x=>x.Id),("status","asc")=>q.OrderBy(x=>x.Status).ThenBy(x=>x.Id),("tarifffraction","asc")=>q.OrderBy(x=>x.TariffFraction).ThenBy(x=>x.Id),_=>q.OrderByDescending(x=>x.EntryDate).ThenBy(x=>x.Id)};return Results.Ok(await Page(q,page,pageSize,cfg,ct));});
    immex.MapGet("/inventory/{id:guid}",async(Guid id,SaceDbContext db,CancellationToken ct)=>{var item=await db.ImmexInventoryEntries.AsNoTracking().AsSplitQuery().Include(x=>x.Material).Include(x=>x.ImmexProgram).Include(x=>x.TemporalRule).ThenInclude(x=>x!.OfficialSourceCitation).Include(x=>x.Discharges).ThenInclude(x=>x.InventoryExit).Include(x=>x.Discharges).ThenInclude(x=>x.Reversal).SingleOrDefaultAsync(x=>x.Id==id,ct);if(item is null)return Results.NotFound(Error("ENTRY_NOT_FOUND","Entrada IMMEX no localizada."));var usage=item.MaterialId.HasValue?await db.ImmexMaterialUsages.AsNoTracking().Where(x=>x.MaterialId==item.MaterialId&&x.PeriodEnd>=item.EntryDate).OrderBy(x=>x.PeriodStart).ToListAsync(ct):[];var issues=await db.ImmexInventoryIssues.AsNoTracking().Where(x=>x.InventoryEntryId==id).OrderByDescending(x=>x.DetectedAt).ToListAsync(ct);var days=item.DueDate.HasValue?(item.DueDate.Value.Date-DateTime.UtcNow.Date).Days:(int?)null;var temporality=new{ruleCode=item.TemporalityRuleCode,ruleVersion=item.TemporalityRuleVersion,item.DueDate,outcome=item.TemporalityOutcome,daysRemaining=days>=0?days:null,daysPastDue=days<0?-days:null,sourceCitation=item.TemporalRule?.OfficialSourceCitation};return Results.Ok(new{entry=item,discharged=item.OriginalQuantity-item.AvailableQuantity,temporality,usage,issues});});
    immex.MapPatch("/inventory/{id:guid}/qualify",async(Guid id,ImmexInventoryQualificationRequest request,HttpContext ctx,SaceDbContext db,IImmexTemporalityService temporality,CancellationToken ct)=>{var item=await db.ImmexInventoryEntries.SingleOrDefaultAsync(x=>x.Id==id,ct);if(item is null)return Results.NotFound(Error("ENTRY_NOT_FOUND","Entrada IMMEX no localizada."));var material=await db.ImmexMaterials.AsNoTracking().SingleOrDefaultAsync(x=>x.Id==request.MaterialId&&x.ImmexProgramId==item.ImmexProgramId&&x.IsActive,ct);if(material is null)return Results.NotFound(Error("IMMEX_MATERIAL_NOT_FOUND","Material activo no localizado en el programa de la entrada."));item.MaterialId=material.Id;item.PartNumber=material.MaterialCode;item.InventoryClassification=request.InventoryClassification;var result=await temporality.CalculateAsync(item,DateTime.UtcNow.Date,ct);item.TemporalRuleId=result.RuleId;item.TemporalityRuleCode=result.RuleCode;item.TemporalityRuleVersion=result.RuleVersion;item.DueDate=result.DueDate;item.TemporalityOutcome=result.Outcome;item.TemporalityCalculatedAt=DateTime.UtcNow;item.TemporalityExplanation=result.Explanation;item.Status=result.Outcome==ImmexTemporalityOutcome.PAST_DUE?ImmexInventoryEntryStatus.PAST_DUE:ImmexInventoryEntryStatus.OPEN;item.UpdatedAt=DateTime.UtcNow;Audit(db,ctx,"IMMEX_ENTRY_CONFIRMED",item,$"Material {material.MaterialCode}; clasificación {request.InventoryClassification}; regla {result.RuleCode??"sin regla"}.");await db.SaveChangesAsync(ct);return Results.Ok(new{entry=item,temporality=result});});
    immex.MapPost("/inventory/import-operation/{operationId:guid}",async(Guid operationId,HttpContext ctx,IImmexInventoryImportService service,CancellationToken ct)=>Results.Ok(await service.ImportOperationAsync(operationId,ctx.User.UserId(),ct)));
