    immex.MapPost("/material-usage",async(ImmexMaterialUsageRequest request,HttpContext ctx,SaceDbContext db,CancellationToken ct)=>{if(request.QuantityUsed<0||request.LossQuantity<0||request.WasteQuantity<0)throw new InvalidOperationException("Las cantidades no pueden ser negativas.");var item=new ImmexMaterialUsage{ImmexProgramId=request.ImmexProgramId,ProductId=request.ProductId,MaterialId=request.MaterialId,PeriodStart=request.PeriodStart,PeriodEnd=request.PeriodEnd,QuantityUsed=request.QuantityUsed,LossQuantity=request.LossQuantity,WasteQuantity=request.WasteQuantity,Unit=Unit(request.Unit),SourceType=request.SourceType,SourceDocumentId=request.SourceDocumentId,SourceFieldId=request.SourceFieldId};db.ImmexMaterialUsages.Add(item);Audit(db,ctx,"IMMEX_MATERIAL_USAGE_CREATED",item,$"Consumo {item.QuantityUsed}; merma {item.LossQuantity}; desperdicio {item.WasteQuantity} {item.Unit}.");await db.SaveChangesAsync(ct);return Results.Created($"/api/immex/material-usage/{item.Id}",item);});
    immex.MapGet("/material-usage",async(Guid? programId,Guid? materialId,Guid? productId,DateTime? from,DateTime? to,int page,int pageSize,SaceDbContext db,IConfiguration cfg,CancellationToken ct)=>{var q=db.ImmexMaterialUsages.AsNoTracking().Include(x=>x.Material).Include(x=>x.Product).AsQueryable();if(programId.HasValue)q=q.Where(x=>x.ImmexProgramId==programId);if(materialId.HasValue)q=q.Where(x=>x.MaterialId==materialId);if(productId.HasValue)q=q.Where(x=>x.ProductId==productId);if(from.HasValue)q=q.Where(x=>x.PeriodEnd>=from);if(to.HasValue)q=q.Where(x=>x.PeriodStart<to.Value.Date.AddDays(1));return Results.Ok(await Page(q.OrderByDescending(x=>x.PeriodEnd).ThenBy(x=>x.Id),page,pageSize,cfg,ct));});

