    immex.MapGet("/temporalities",async(Guid? programId,string? outcome,int page,int pageSize,SaceDbContext db,IConfiguration cfg,CancellationToken ct)=>{var q=db.ImmexInventoryEntries.AsNoTracking().Where(x=>x.AvailableQuantity>0);if(programId.HasValue)q=q.Where(x=>x.ImmexProgramId==programId);if(Enum.TryParse<ImmexTemporalityOutcome>(outcome,true,out var o))q=q.Where(x=>x.TemporalityOutcome==o);return Results.Ok(await Page(q.OrderBy(x=>x.DueDate),page,pageSize,cfg,ct));});
    immex.MapGet("/temporalities/rules",async(SaceDbContext db,CancellationToken ct)=>Results.Ok(await db.ImmexTemporalityRules.AsNoTracking().Include(x=>x.OfficialSourceCitation).ThenInclude(x=>x!.OfficialLegalSourceVersion).ThenInclude(x=>x.OfficialLegalSource).OrderBy(x=>x.Code).ThenByDescending(x=>x.Version).ToListAsync(ct)));
