    immex.MapGet("/temporalities/alerts",async(Guid? programId,SaceDbContext db,CancellationToken ct)=>{var q=db.ImmexInventoryEntries.AsNoTracking().Where(x=>x.AvailableQuantity>0&&new[]{ImmexTemporalityOutcome.DUE_SOON,ImmexTemporalityOutcome.DUE_CRITICAL,ImmexTemporalityOutcome.PAST_DUE,ImmexTemporalityOutcome.MANUAL_REVIEW}.Contains(x.TemporalityOutcome));if(programId.HasValue)q=q.Where(x=>x.ImmexProgramId==programId);var rows=await q.OrderBy(x=>x.DueDate).Select(x=>new{x.Id,x.PedimentoNumber,x.PartNumber,x.AvailableQuantity,x.TigieUnit,x.DueDate,x.TemporalityOutcome}).ToListAsync(ct);return Results.Ok(rows.Select(x=>new{x.Id,x.PedimentoNumber,x.PartNumber,x.AvailableQuantity,x.TigieUnit,x.DueDate,x.TemporalityOutcome,daysRemaining=x.DueDate.HasValue?(x.DueDate.Value.Date-DateTime.UtcNow.Date).Days:(int?)null}));});

    immex.MapGet("/fixed-assets",async(Guid? programId,int page,int pageSize,SaceDbContext db,IConfiguration cfg,CancellationToken ct)=>{var q=db.ImmexFixedAssets.AsNoTracking().AsQueryable();if(programId.HasValue)q=q.Where(x=>x.ImmexProgramId==programId);return Results.Ok(await Page(q.OrderByDescending(x=>x.EntryDate),page,pageSize,cfg,ct));});
    immex.MapGet("/fixed-assets/{id:guid}",async(Guid id,SaceDbContext db,CancellationToken ct)=>await db.ImmexFixedAssets.AsNoTracking().SingleOrDefaultAsync(x=>x.Id==id,ct) is{} item?Results.Ok(item):Results.NotFound(Error("IMMEX_FIXED_ASSET_NOT_FOUND","Activo fijo no localizado.")));
    immex.MapPost("/fixed-assets",async(ImmexFixedAssetRequest request,HttpContext ctx,SaceDbContext db,CancellationToken ct)=>{var item=new ImmexFixedAsset{ImmexProgramId=request.ImmexProgramId,TradeOperationId=request.TradeOperationId,Description=Required(request.Description,"Description"),Brand=Clean(request.Brand),Model=Clean(request.Model),SerialNumber=Clean(request.SerialNumber),TariffFraction=string.IsNullOrWhiteSpace(request.TariffFraction)?null:Tariff(request.TariffFraction),Nico=Clean(request.Nico),PedimentoNumber=Required(request.PedimentoNumber,"PedimentoNumber"),PedimentoKey=Required(request.PedimentoKey,"PedimentoKey"),EntryDate=request.EntryDate,Status=request.Status};db.ImmexFixedAssets.Add(item);Audit(db,ctx,"IMMEX_FIXED_ASSET_CREATED",item,$"Activo fijo del pedimento {item.PedimentoNumber}.");await db.SaveChangesAsync(ct);return Results.Created($"/api/immex/fixed-assets/{item.Id}",item);});
