    immex.MapPost("/unit-conversions",async(ImmexUnitConversionRequest request,HttpContext ctx,SaceDbContext db,CancellationToken ct)=>{if(request.Factor<=0)throw new InvalidOperationException("Factor debe ser mayor que cero.");var item=new ImmexUnitConversion{MaterialId=request.MaterialId,FromUnit=Unit(request.FromUnit),ToUnit=Unit(request.ToUnit),Factor=request.Factor,EffectiveFrom=request.EffectiveFrom,EffectiveTo=request.EffectiveTo,Source=Required(request.Source,"Source"),IsVerified=request.IsVerified};db.ImmexUnitConversions.Add(item);Audit(db,ctx,"IMMEX_UNIT_CONVERSION_CREATED",item,$"{item.FromUnit} → {item.ToUnit}; factor verificado={item.IsVerified}.");await db.SaveChangesAsync(ct);return Results.Created($"/api/immex/unit-conversions/{item.Id}",item);});
