    immex.MapPatch("/issues/{id:guid}",async(Guid id,ImmexIssueStatus status,string? resolution,HttpContext ctx,SaceDbContext db,CancellationToken ct)=>{var item=await db.ImmexInventoryIssues.FindAsync([id],ct);if(item is null)return Results.NotFound(Error("IMMEX_ISSUE_NOT_FOUND","Issue no localizado."));var closing=status is ImmexIssueStatus.RESOLVED or ImmexIssueStatus.DISMISSED;if(closing&&string.IsNullOrWhiteSpace(resolution))throw new InvalidOperationException("Resolution es obligatoria para cerrar un issue.");item.Status=status;item.Resolution=Clean(resolution);item.ResolvedAt=closing?DateTime.UtcNow:null;item.ResolvedBy=item.ResolvedAt.HasValue?ctx.User.UserId():null;Audit(db,ctx,closing?"IMMEX_ISSUE_RESOLVED":"IMMEX_ISSUE_STATUS_CHANGED",item,$"Estado {status}; {item.Resolution}");await db.SaveChangesAsync(ct);return Results.Ok(item);});

    immex.MapGet("/dashboard",async(Guid? programId,SaceDbContext db,IConfiguration cfg,CancellationToken ct)=>{var q=db.ImmexInventoryEntries.AsNoTracking().AsQueryable();if(programId.HasValue)q=q.Where(x=>x.ImmexProgramId==programId);var rows=await q.Select(x=>new{x.Id,x.MaterialId,material=x.Material==null?x.PartNumber:x.Material.MaterialCode,description=x.Material==null?x.Description:x.Material.Description,x.TariffFraction,x.PedimentoNumber,x.OriginalQuantity,x.AvailableQuantity,x.TigieUnit,x.EntryDate,x.DueDate,x.Status,x.TemporalityOutcome}).ToListAsync(ct);var issueQ=db.ImmexInventoryIssues.AsNoTracking().Where(x=>x.Status==ImmexIssueStatus.OPEN);if(programId.HasValue)issueQ=issueQ.Where(x=>x.ImmexProgramId==programId);var assetQ=db.ImmexFixedAssets.AsNoTracking().Where(x=>x.Status==ImmexFixedAssetStatus.OPEN);if(programId.HasValue)assetQ=assetQ.Where(x=>x.ImmexProgramId==programId);var top=rows.Where(x=>x.AvailableQuantity>0).GroupBy(x=>new{x.MaterialId,x.material,x.description,x.TariffFraction,x.TigieUnit}).Select(x=>new{x.Key.MaterialId,x.Key.material,x.Key.description,x.Key.TariffFraction,x.Key.TigieUnit,balance=x.Sum(y=>y.AvailableQuantity),oldest=x.Min(y=>y.EntryDate),dueDate=x.Min(y=>y.DueDate),status=x.OrderByDescending(y=>Severity(y.TemporalityOutcome)).First().TemporalityOutcome}).OrderByDescending(x=>x.balance).Take(10);var distribution=new{over90=rows.Count(x=>x.DueDate.HasValue&&(x.DueDate.Value.Date-DateTime.UtcNow.Date).Days>90),days31To90=rows.Count(x=>x.DueDate.HasValue&&(x.DueDate.Value.Date-DateTime.UtcNow.Date).Days is >=31 and <=90),days1To30=rows.Count(x=>x.DueDate.HasValue&&(x.DueDate.Value.Date-DateTime.UtcNow.Date).Days is >=1 and <=30),pastDue=rows.Count(x=>x.TemporalityOutcome==ImmexTemporalityOutcome.PAST_DUE),undetermined=rows.Count(x=>x.DueDate==null)};return Results.Ok(new{kpis=new{openTemporaryImports=rows.Count(x=>x.AvailableQuantity>0),pendingBalance=rows.Sum(x=>x.AvailableQuantity),dueSoon=rows.Count(x=>x.TemporalityOutcome==ImmexTemporalityOutcome.DUE_SOON),critical=rows.Count(x=>x.TemporalityOutcome==ImmexTemporalityOutcome.DUE_CRITICAL),pastDue=rows.Count(x=>x.TemporalityOutcome==ImmexTemporalityOutcome.PAST_DUE),discharged=rows.Count(x=>x.AvailableQuantity==0),openIssues=await issueQ.CountAsync(ct),openFixedAssets=await assetQ.CountAsync(ct)},distribution,topBalances=top,thresholds=new{dueSoonDays=cfg.GetValue("ImmexInventory:DueSoonDays",90),criticalDays=cfg.GetValue("ImmexInventory:CriticalDays",30)},disclaimer="Indicador técnico interno basado en operaciones registradas en SACE; no constituye una conclusión jurídica."});});

    MapReports(immex);
    api.MapGet("/operations/{operationId:guid}/immex",async(Guid operationId,SaceDbContext db,CancellationToken ct)=>{var operation=await db.TradeOperations.AsNoTracking().Where(x=>x.Id==operationId).Select(x=>new{x.Id,x.ImmexProgramId,x.IsTemporaryImport,x.CustomsRegimeCode,x.IsImmex}).SingleOrDefaultAsync(ct);if(operation is null)return Results.NotFound(Error("OPERATION_NOT_FOUND","Operación no localizada."));var entries=await db.ImmexInventoryEntries.AsNoTracking().Where(x=>x.TradeOperationId==operationId).Include(x=>x.Material).Include(x=>x.Discharges).ThenInclude(x=>x.InventoryExit).ToListAsync(ct);var ids=entries.Select(x=>x.Id).ToList();var issues=await db.ImmexInventoryIssues.AsNoTracking().Where(x=>x.InventoryEntryId.HasValue&&ids.Contains(x.InventoryEntryId.Value)).ToListAsync(ct);return Results.Ok(new{operation,entries,issues});});
    api.MapPatch("/operations/{operationId:guid}/immex",async(Guid operationId,ImmexOperationLinkRequest request,HttpContext ctx,SaceDbContext db,CancellationToken ct)=>{var operation=await db.TradeOperations.FindAsync([operationId],ct);if(operation is null)return Results.NotFound(Error("OPERATION_NOT_FOUND","Operación no localizada."));if(request.ImmexProgramId.HasValue&&!await db.ImmexPrograms.AnyAsync(x=>x.Id==request.ImmexProgramId,ct))return Results.NotFound(Error("IMMEX_PROGRAM_NOT_FOUND","Programa IMMEX no localizado."));operation.ImmexProgramId=request.ImmexProgramId;operation.IsTemporaryImport=request.IsTemporaryImport;operation.CustomsRegimeCode=Clean(request.CustomsRegimeCode);operation.UpdatedAt=DateTime.UtcNow;Audit(db,ctx,"IMMEX_OPERATION_LINK_UPDATED",operation,$"Programa={request.ImmexProgramId}; temporal={request.IsTemporaryImport}; régimen={operation.CustomsRegimeCode}.");await db.SaveChangesAsync(ct);return Results.Ok(operation);});
    return immex;
  }

  static void MapReports(RouteGroupBuilder immex){
    immex.MapGet("/reports/entries",async(Guid? programId,DateTime? from,DateTime? to,string? format,SaceDbContext db,CancellationToken ct)=>{var q=db.ImmexInventoryEntries.AsNoTracking().Include(x=>x.Material).AsQueryable();if(programId.HasValue)q=q.Where(x=>x.ImmexProgramId==programId);if(from.HasValue)q=q.Where(x=>x.EntryDate>=from);if(to.HasValue)q=q.Where(x=>x.EntryDate<to.Value.Date.AddDays(1));var rows=await q.OrderBy(x=>x.EntryDate).Select(x=>new{x.PedimentoNumber,x.PedimentoKey,x.PedimentoItemNumber,x.EntryDate,Material=x.Material==null?x.PartNumber:x.Material.MaterialCode,x.TariffFraction,x.Nico,x.OriginalQuantity,x.AvailableQuantity,x.TigieUnit,x.Status}).ToListAsync(ct);return Report(rows,format,"immex-entries.csv");});
    immex.MapGet("/reports/exits",async(Guid? programId,DateTime? from,DateTime? to,string? format,SaceDbContext db,CancellationToken ct)=>{var q=db.ImmexInventoryExits.AsNoTracking().Include(x=>x.Material).AsQueryable();if(programId.HasValue)q=q.Where(x=>x.ImmexProgramId==programId);if(from.HasValue)q=q.Where(x=>x.ExitDate>=from);if(to.HasValue)q=q.Where(x=>x.ExitDate<to.Value.Date.AddDays(1));var rows=await q.OrderBy(x=>x.ExitDate).Select(x=>new{x.PedimentoNumber,x.ExitDate,x.PedimentoKey,x.ExitType,Material=x.Material==null?null:x.Material.MaterialCode,x.Quantity,x.AllocatedQuantity,x.UnallocatedQuantity,x.Unit,x.DischargeOutcome}).ToListAsync(ct);return Report(rows,format,"immex-exits.csv");});
    immex.MapGet("/reports/balances",async(Guid? programId,DateTime? from,DateTime? to,string? format,SaceDbContext db,CancellationToken ct)=>{var q=db.ImmexInventoryEntries.AsNoTracking().Include(x=>x.Material).AsQueryable();if(programId.HasValue)q=q.Where(x=>x.ImmexProgramId==programId);if(from.HasValue)q=q.Where(x=>x.EntryDate>=from);if(to.HasValue)q=q.Where(x=>x.EntryDate<to.Value.Date.AddDays(1));var data=await q.Select(x=>new{x.MaterialId,Material=x.Material==null?x.PartNumber:x.Material.MaterialCode,Description=x.Material==null?x.Description:x.Material.Description,x.TariffFraction,x.OriginalQuantity,x.AvailableQuantity,x.TigieUnit,x.EntryDate,x.DueDate,x.PedimentoNumber,x.TemporalityOutcome}).ToListAsync(ct);var rows=data.GroupBy(x=>new{x.MaterialId,x.Material,x.Description,x.TariffFraction,x.TigieUnit}).Select(x=>new{x.Key.Material,x.Key.Description,x.Key.TariffFraction,Original=x.Sum(y=>y.OriginalQuantity),Discharged=x.Sum(y=>y.OriginalQuantity-y.AvailableQuantity),Available=x.Sum(y=>y.AvailableQuantity),Unit=x.Key.TigieUnit,OpenPedimentos=x.Count(y=>y.AvailableQuantity>0),OldestEntry=x.Min(y=>y.EntryDate),NearestDue=x.Min(y=>y.DueDate),Status=x.OrderByDescending(y=>Severity(y.TemporalityOutcome)).First().TemporalityOutcome}).OrderBy(x=>x.TariffFraction).ToList();return Report(rows,format,"immex-balances.csv");});
    immex.MapGet("/reports/material-usage",async(Guid? programId,DateTime? from,DateTime? to,Guid? materialId,Guid? productId,string? format,SaceDbContext db,CancellationToken ct)=>{var q=db.ImmexMaterialUsages.AsNoTracking().Include(x=>x.Material).Include(x=>x.Product).AsQueryable();if(programId.HasValue)q=q.Where(x=>x.ImmexProgramId==programId);if(from.HasValue)q=q.Where(x=>x.PeriodEnd>=from);if(to.HasValue)q=q.Where(x=>x.PeriodStart<to.Value.Date.AddDays(1));if(materialId.HasValue)q=q.Where(x=>x.MaterialId==materialId);if(productId.HasValue)q=q.Where(x=>x.ProductId==productId);var rows=await q.OrderBy(x=>x.PeriodStart).Select(x=>new{Material=x.Material.MaterialCode,Product=x.Product==null?null:x.Product.ProductCode,x.PeriodStart,x.PeriodEnd,x.QuantityUsed,x.LossQuantity,x.WasteQuantity,x.Unit,x.SourceType}).ToListAsync(ct);return Report(rows,format,"immex-material-usage.csv");});
  }
  static IResult Report<T>(IReadOnlyList<T> rows,string? format,string fileName){if(!string.Equals(format,"csv",StringComparison.OrdinalIgnoreCase))return Results.Ok(new{disclaimer="Reporte generado por SACE a partir de la información registrada en el sistema.",items=rows});var properties=typeof(T).GetProperties();var sb=new StringBuilder();sb.AppendLine(string.Join(',',properties.Select(x=>Csv(x.Name))));foreach(var row in rows)sb.AppendLine(string.Join(',',properties.Select(x=>Csv(x.GetValue(row)?.ToString()??""))));var bytes=Encoding.UTF8.GetPreamble().Concat(Encoding.UTF8.GetBytes(sb.ToString())).ToArray();return Results.File(bytes,"text/csv; charset=utf-8",fileName);}
  static string Csv(string value)=>$"\"{value.Replace("\"","\"\"")}\"";
  static async Task<object> Page<T>(IQueryable<T> query,int page,int pageSize,IConfiguration cfg,CancellationToken ct){page=Math.Max(1,page);pageSize=Math.Clamp(pageSize==0?20:pageSize,1,cfg.GetValue("Pagination:MaxPageSize",100));var total=await query.CountAsync(ct);var items=await query.Skip((page-1)*pageSize).Take(pageSize).ToListAsync(ct);return new{items,total,page,pageSize,pages=(int)Math.Ceiling(total/(double)pageSize)};}
  static ImmexMaterial Material(ImmexMaterialRequest r,string code)=>new(){ImmexProgramId=r.ImmexProgramId,MaterialCode=code,Description=Required(r.Description,"Description"),TariffFraction=Tariff(r.TariffFraction),Nico=Clean(r.Nico),TigieUnit=Unit(r.TigieUnit),CommercialUnit=Clean(r.CommercialUnit),IsActive=r.IsActive};
  static ImmexProduct Product(ImmexProductRequest r,string code)=>new(){ImmexProgramId=r.ImmexProgramId,ProductCode=code,Description=Required(r.Description,"Description"),TariffFraction=Tariff(r.TariffFraction),Nico=Clean(r.Nico),TigieUnit=Unit(r.TigieUnit),CommercialUnit=Clean(r.CommercialUnit),IsActive=r.IsActive};
  static void ValidateProgram(ImmexProgramRequest r){Required(r.ProgramNumber,"ProgramNumber");Required(r.CompanyName,"CompanyName");Required(r.Rfc,"Rfc");if(r.ValidFrom.HasValue&&r.ValidTo.HasValue&&r.ValidTo<r.ValidFrom)throw new InvalidOperationException("ValidTo no puede ser anterior a ValidFrom.");}
  static async Task ValidateProgramExists(Guid id,SaceDbContext db,CancellationToken ct){if(!await db.ImmexPrograms.AnyAsync(x=>x.Id==id,ct))throw new KeyNotFoundException("IMMEX_PROGRAM_NOT_FOUND");}
  static string Required(string value,string field)=>string.IsNullOrWhiteSpace(value)?throw new InvalidOperationException($"{field} es obligatorio."):value.Trim();static string? Clean(string? value)=>string.IsNullOrWhiteSpace(value)?null:value.Trim();static string Unit(string value)=>Required(value,"Unit").ToUpperInvariant();static string Tariff(string value){var digits=new string(Required(value,"TariffFraction").Where(char.IsDigit).ToArray());if(digits.Length>8)digits=digits[..8];return digits.PadLeft(8,'0');}
  static int Severity(ImmexTemporalityOutcome value)=>value switch{ImmexTemporalityOutcome.PAST_DUE=>5,ImmexTemporalityOutcome.DUE_CRITICAL=>4,ImmexTemporalityOutcome.DUE_SOON=>3,ImmexTemporalityOutcome.MANUAL_REVIEW=>2,ImmexTemporalityOutcome.INSUFFICIENT_DATA=>1,_=>0};
  static ApiError Error(string code,string message)=>new(404,code,message,new{});static void Audit(SaceDbContext db,HttpContext ctx,string action,object entity,string details){var id=(Guid)(entity.GetType().GetProperty("Id")?.GetValue(entity)??Guid.Empty);var user=ctx.User.UserId();db.SystemAuditLogs.Add(new(){UserId=user==Guid.Empty?null:user,Action=action,EntityType=entity.GetType().Name,EntityId=id.ToString(),Details=details});}
}
